    {"id": "to-yperokeaneion", "cat": "berth", "tier": "berth_top", "priority": 2, "badge": "8 tables", "name": "To Yperokeaneion", "short": "To Yperokeaneion", "lat": 37.93696, "lng": 23.63032, "neighborhood": "Hatzikyriakio · the coastal fish-taverna strip", "tags": ["€€ · ~€18–22pp", "Essential — tiny room", "Summer evening, on the terrace"], "productTags": ["Charcoal sardines", "Kimolos ladenia", "Raki"], "why": "Andreas Kontsos captained ships out of Kimolos before he cooked, and he kept what the sea left him: anchors, ropes, ocean-liner memorabilia. After running the 1990s Piraeus spot Karpouzi, he opened this small room in a former nautical warehouse and named it after the liners that carried Greek emigrants to Australia. On good nights there is ladenia, the Kimolos tomato-and-onion flatbread, next to the charcoal sardines.", "address": "Marias Chatzikyriakou 48, 185 38 Piraeus", "phone": "+30 210 4180030", "hours": "Call ahead: the old record says dinner only; a 2023 review and listings describe noon opening and lunch before the ferries", "maps": "https://www.google.com/maps/search/?api=1&query=To+Yperokeaneion+Piraeus", "verdict": "A pocket seafood ouzeri of eight tables that pulls Italians and Athenians down to Hatzikyriakio at ~€20pp — worth the reservation for the room and the fish, not for anyone in a group or after meat.", "signature": "Charcoal-grilled sardines on oiled bread: charred, salt-bright, oily; and, on lucky nights, the owner's Kimolos ladenia.", "caveat": "Tiny and fish-only — not for large groups, walk-ins, or meat-eaters.", "person": "Andreas Kontsos, a ship's captain from Kimolos and collector of maritime antiques, who ran the 1990s landmark 'Karpouzi' before opening this room.", "signal_chip": {"label": "LiFO 2024", "full": "LiFO 2024 — 'the classic value of Piraeus for fish and seafood'", "cosign": "Ten years in and still eight tables — we stand by the room."}, "dishes": [{"name": "Grilled sardines on bread", "note": "charred, oily, the house-defining plate", "kind": "dish"}, {"name": "Ladenia Kimolou", "note": "island tomato-onion flatbread, the owner's Kimolos signature", "kind": "dish"}, {"name": "Grilled cuttlefish with tahini & tomato", "note": "tender soupies, sesame-savoury sauce", "kind": "dish"}, {"name": "Fried atherina (whitebait)", "note": "crisp, whole, lemon-lashed", "kind": "dish"}, {"name": "Mussels saganaki with garlic", "note": "crumbed mydia, garlicky and hot", "kind": "dish"}, {"name": "Ouzo / Cretan raki", "note": "poured from the barrel alongside bulk wine", "kind": "drink"}], "price_range": "€€ · ~€18–22pp", "reservation": "Essential — tiny room", "best_time": "Summer evening, on the terrace", "status": "confirmed", "statusChecked": "2026-10-14", "hook": "A former ship captain's small seafood ouzeri in Hatzikyriakio, its walls hung with his maritime collection.", "category": "ouzeri", "charter": {"price": "€€ · ~€18–22pp", "book": "Essential — tiny room", "warn": "Tiny and fish-only — not for large groups, walk-ins, or meat-eaters.", "fit": "A former ship captain's small seafood ouzeri in Hatzikyriakio, its walls hung with his maritime collection."}},
    {"id": "dyosmos", "cat": "shop", "tier": "plenty", "priority": 11, "badge": "Producers", "name": "Dyosmos", "short": "Dyosmos", "lat": 37.9332, "lng": 23.64449, "neighborhood": "Freattyda · Leoforos Freattydos", "tags": ["€/€€ · many mezedes under €15", "Book weekends", "Evening, in the neoclassical room"], "productTags": ["Cretan staka pasta", "Schinousa fava", "Tsipouro"], "why": "The house is a 1920 neoclassical built by an architect who arrived by boat from Constantinople and settled in Freattyda. Since September 2015 it has been a meze room run by Stelios Parashos, with Nikos Omaris, trained at Selini on Santorini, building the menu from small named producers: staka from Crete, fava from Schinousa, kasseri from Xanthi, cured ham from Evrytania. In summer the tables move up to a roof terrace.", "address": "Leof. Freattydos 42A, Freattyda, Piraeus", "phone": "+30 210 4611335", "hours": "Call ahead: Tripadvisor and e-table give Mon-Fri 18:00-01:00, Sat-Sun 13:00-01:00 (undated); an older e-restaurants listing opens 17:00 on weekdays", "maps": "https://www.google.com/maps/search/?api=1&query=Dyosmos+Freattyda+Piraeus", "verdict": "A meze kitchen built producer by producer, plating Cretan staka pasta and Schinousa fava in a 1920 neoclassical room with most small plates under €15 — the most identity-driven table in Freattyda, and not a sea-view fry-joint.", "signature": "Cretan pasta with smoked pork and staka: handmade pasta, smoked pork, melting sheep-butter staka cream, salt-bright — around €9.", "caveat": "Not a sea-view harbour taverna nor a cheap-fry joint — it's an ingredient-led room.", "person": "Chef Nikos Omaris, trained at Selini on Santorini, runs the kitchen; the proprietor is Stelios Parashos.", "signal_chip": {"label": "LiFO 2019", "full": "LiFO 2019 — 'Greek cooking with a strong identity' in Freattyda", "cosign": "You taste the sourcing — we back the producer-by-producer bet."}, "dishes": [{"name": "Cretan pasta with smoked pork and staka cream", "note": "handmade pasta, smoked pork, melting sheep-butter staka (~€9)", "kind": "dish"}, {"name": "Schinousa fava with Eurytania prosciutto", "note": "silky split-pea purée, cured-meat salt", "kind": "dish"}, {"name": "Mushroom sauté with Xanthi kasseri", "note": "earthy mushrooms, melted regional cheese", "kind": "dish"}, {"name": "Tzoumagia sausage with mustard & rakomelo", "note": "village sausage glazed sweet-sharp", "kind": "dish"}, {"name": "Aegean shrimp pasta", "note": "sweet gambari over pasta", "kind": "dish"}, {"name": "Tsipouro / ouzo", "note": "poured to carry the small plates", "kind": "drink"}], "price_range": "€/€€ · many mezedes under €15", "reservation": "Book weekends", "best_time": "Evening, in the neoclassical room", "status": "unverified", "statusChecked": "2026-10-14", "hook": "A producer-led meze room in a 1920 Freattyda neoclassical, with a roof terrace in summer.", "web": "https://diosmos.gr", "category": "ouzeri", "charter": {"price": "€/€€ · many mezedes under €15", "book": "Book weekends", "warn": "Not a sea-view harbour taverna nor a cheap-fry joint — it's an ingredient-led room.", "fit": "A producer-led meze room in a 1920 Freattyda neoclassical, with a roof terrace in summer."}},
    {"id": "ikariotiko-kafeneio", "cat": "shop", "tier": "plenty", "priority": 12, "badge": "Ikarian", "name": "Ikariotiko Kafeneio", "short": "Ikariotiko Kafeneio", "lat": 37.94646, "lng": 23.64268, "neighborhood": "Central Piraeus · Aristeidou St, off the port gates", "tags": ["€ · cheap tsipouro-and-meze", "None — walk in", "Afternoon, over tavli"], "productTags": ["Tsipouro", "Fava", "Meze plates"], "why": "For about seventy years this kafenio has poured for the Ikarian community of Piraeus, its walls covered with photographs and murals of the island. Sailors and shipyard hands come for tsipouro with cheese and olives brought from Ikaria. When the 1956 building on Akti Poseidonos that housed it was taken back for redevelopment, the regulars moved the whole kafenio a few streets inland; LiFO reported the move in August 2023. Nikos, 'the Ikarian', keeps the counter.", "address": "Aristeidou 17, Piraeus", "phone": "+30 210 4130090", "hours": "Daytime into evening; kafenio hours, walk-in", "maps": "https://www.google.com/maps/search/?api=1&query=Ikariotiko+Kafeneio+Piraeus", "verdict": "Retired Ikarian sailors playing tavli, cheap tsipouro, and mezedes that arrive unbidden without a card — the most island-true kafenio near the port gates, never a dinner destination.", "signature": "Cold tsipouro with fava, keftedakia and dolmades: split-pea purée, little fried meatballs, tight vine leaves, plate after plate.", "caveat": "Not a destination dinner and no view — a smoky, no-frills community kafenio.", "person": "Nikos, 'the Ikarian', thirty-five years behind the counter of this Ikarian sailors' kafenio.", "signal_chip": {"label": "GGG pick", "full": "Greek Gastronomy Guide — a listed Piraeus landmark kafenio", "cosign": "Carried three streets in 2023 and unchanged — we back its stubbornness."}, "dishes": [{"name": "Fava", "note": "yellow split-pea purée, onion and oil", "kind": "dish"}, {"name": "Loukaniko (sausage)", "note": "griddled village sausage", "kind": "dish"}, {"name": "Dolmades", "note": "vine leaves rolled tight", "kind": "dish"}, {"name": "Keftedakia", "note": "little fried meatballs, herb-flecked", "kind": "dish"}, {"name": "Fried potatoes", "note": "hand-cut, salt-hot", "kind": "dish"}, {"name": "Tsipouro / ouzo", "note": "the reason the kafenio exists", "kind": "drink"}], "price_range": "€ · cheap tsipouro-and-meze", "reservation": "None — walk in", "best_time": "Afternoon, over tavli", "status": "unverified", "statusChecked": "2026-10-14", "hook": "An Ikarian sailors' kafenio near the port gates: tsipouro, tavli and mezedes that arrive unasked.", "category": "ouzeri"},
    {"id": "to-eidikon", "cat": "shop", "tier": "plenty", "priority": 13, "badge": "Est.1920", "name": "To Eidikon", "short": "To Eidikon", "lat": 37.95564, "lng": 23.63379, "neighborhood": "Agios Dionysios · Psaron & Salaminos, behind the Papastrateio", "tags": ["€ · cheap meze, barrel wine", "No — walk in", "Weekday early evening, before the room fills"], "productTags": ["Barrel retsina", "Meze", "Fried eggs"], "why": "Aristeidis Papakonstantinou came down from Gardiki, near Trikala, and opened this grocery and wine shop in 1920; the same family has run it since. Holes in the metal shutter were left by German bullets during the Occupation and kept on purpose. The retsina is the family's own, and the plates are what a corner grocer would cook: fried liver, meatballs, potatoes under eggs. On some nights groups arrive with instruments and the room sings.", "address": "Psaron 38 & Salaminos, Piraeus", "phone": "+30 210 4612674", "hours": "Midday into evening; call to confirm the day", "maps": "https://www.google.com/maps/search/?api=1&query=To+Eidikon+Piraeus", "verdict": "The last true barrel-wine oinopantopoleio in Piraeus — a 1920 room where the retsina is still pressed in the cellar directly below your table.", "signature": "Cellar retsina: cold and resin-sharp, poured beside fried potatoes under four runny eggs.", "caveat": "Not for anyone wanting a menu, a wine list or polish — five or six mezedes and barrel retsina, cash-simple, in a cramped old room.", "person": "Family Papakonstantinou — founded 1920 by Aristeidis (from Gardiki, Trikala); now third generation, son Apostolos and grandson Aristeidis, with Voula cooking the mezedes.", "signal_chip": {"label": "LiFO", "full": "LiFO 2023 — one of 'ten Piraeus shops that wrote history'", "cosign": "the last oinopantopoleio in the port still pressing its own wine."}, "dishes": [{"name": "Cellar retsina", "note": "old-style resinated white drawn from the barrel below the floor", "kind": "drink"}, {"name": "Patates me avga", "note": "fried potatoes crowned with four runny eggs", "kind": "dish"}, {"name": "Keftedes", "note": "hand-rolled meatballs, crisp-edged, cumin warmth", "kind": "dish"}, {"name": "Fried liver (sykoti)", "note": "tender pan-fried liver, lemon, oregano bite", "kind": "dish"}, {"name": "Corned-beef omelette", "note": "old-Greece omelet folded around salt-beef", "kind": "dish"}, {"name": "Fava", "note": "silky yellow split-pea purée, olive oil, raw onion", "kind": "dish"}], "price_range": "€ · cheap meze, barrel wine", "reservation": "Walk in most days; book on live-music nights", "best_time": "Weekday early evening, before the room fills", "status": "unverified", "statusChecked": "2026-10-14", "hook": "A 1920 grocery and wine shop near the port, still pouring the family's own retsina beside simple fry-ups.", "category": "koutoukia"},
    {"id": "propolemikon", "cat": "shop", "tier": "plenty", "priority": 14, "badge": "Est.1896", "name": "Propolemikon", "short": "Propolemikon", "lat": 37.9604, "lng": 23.63762, "neighborhood": "Agios Dionysios · Dervenakion St, behind the port", "tags": ["€–€€", "Advisable on music nights", "A rembetiko night, late"], "productTags": ["Barrel wine", "Magirefta", "Rebetika"], "why": "The stone walls, iron shutters and cellar barrels go back to 1896, when the house opened as an oinomageireio in the Agios Dionysios back streets; between the wars new owners ran it as a grocery-taverna known as Trichas's. LiFO counts it among ten Piraeus shops that wrote history and records that a song by the rebetis Michalis Genitsaris was first sung here. The barrels still hold the house wine, poured by the karafa.", "address": "Dervenakion 22, Agios Dionysios, Piraeus", "phone": "+30 210 4629229", "hours": "Evenings; rebetika Sat 22:00 & Sun 14:00 — call ahead", "maps": "https://www.google.com/maps/search/?api=1&query=Propolemikon+Piraeus", "verdict": "A stone-walled 1896 oinomageireio where the legendary Piraeus rembetiko quartet once played and the house wine still comes from cellar barrels.", "signature": "Barrel wine: rough, cold from the stone cellar, poured under walls that heard Vamvakaris play.", "caveat": "Not for a quiet, refined dinner — a smoky, music-first old room; phone to confirm it is open and whether there is rembetika that night.", "person": "Built by Perama karavomarangoi (shipwrights) as a wine house said to date to 1896 — among the oldest tavernas in Piraeus; the stone-cellar barrels still hold wine made on site.", "signal_chip": {"label": "LiFO", "full": "LiFO 2018 — one of 'ten Piraeus shops that made history'", "cosign": "the stone room where the Piraeus rebetiko tetras played."}, "dishes": [{"name": "Barrel wine (chyma)", "note": "house wine made in the stone cellar, by the karafa", "kind": "drink"}, {"name": "Mageirefta tis imeras", "note": "daily pot dishes from the kitchen, the reason to come", "kind": "dish"}, {"name": "Keftedes", "note": "griddled meatballs, herb and cumin", "kind": "dish"}, {"name": "Loukaniko", "note": "village sausage, charred and coarse", "kind": "dish"}, {"name": "Cheese saganaki", "note": "pan-fried cheese, crisp and salty", "kind": "dish"}, {"name": "Gigantes", "note": "baked butter beans in tomato", "kind": "dish"}], "price_range": "€–€€", "reservation": "Advisable on music nights", "best_time": "A rembetiko night, late", "status": "unverified", "statusChecked": "2026-10-14", "hook": "An 1896 stone wine-house in the Agios Dionysios back streets, with barrel wine and rebetiko history.", "category": "koutoukia", "hot_this_month": "The cold-weather music season in the stone room: rebetika Saturday from 22:00 and Sunday from 14:00 per the venue record; phone to confirm the night (checked 14 Oct 2026)."},
    {"id": "to-koutouki-tou-antoni", "cat": "shop", "tier": "plenty", "priority": 15, "badge": "Fig tree", "name": "To Koutouki tou Antoni", "short": "To Koutouki tou Antoni", "lat": 37.96076, "lng": 23.65764, "neighborhood": "Palaia Kokkinia · alley above Thivon St", "tags": ["€–€€", "Advisable at weekends", "A warm summer night in the courtyard"], "productTags": ["Barrel wine", "Bakaliaros", "Fig-tree yard"], "why": "The koutouki has cooked since 1958 in a lane above Thivon Street in Palaia Kokkinia, the quarter built by refugees after 1922. Its covered courtyard grows around a tall fig tree with a whitewashed trunk, among old tiles and small objects gathered over decades. The business registry names Eirini Vergopoulou as holder; the sign still carries the name of the original Antonis. Wine comes from the barrel by the karafa.", "address": "Argyrokastrou 26, Palaia Kokkinia, 185 42 Piraeus", "phone": "+30 210 4924338", "hours": "Tue–Sat 12:00–24:00, Sun to 17:00; closed Mon", "maps": "https://www.google.com/maps/search/?api=1&query=Koutouki+tou+Antoni+Kokkinia", "verdict": "A 1958 Kokkinia koutouki built around a whitewashed fig tree, where floral-cloth tables and barrel wine make dinner feel like a refugee-quarter courtyard from another century.", "signature": "Bakaliaros skordalia: fried cod with fierce garlic-potato purée, barrel wine, under the fig tree.", "caveat": "Not for the design-conscious or the hurried — deliberately old, tiled and floral; the joy is the courtyard, not the plating.", "person": "Running since 1958 in the heart of the 1922 refugee quarter; held today by Eirini Vergopoulou per the business registry, keeping the name of its original Antonis.", "signal_chip": {"label": "Newsbeast", "full": "Newsbeast 2021 — 'seven authentic koutoukia'", "cosign": "a 1958 fig-tree courtyard, kept unchanged."}, "dishes": [{"name": "Bakaliaros skordalia", "note": "fried cod with punchy garlic-potato purée", "kind": "dish"}, {"name": "Fava", "note": "yellow split-pea purée, olive oil, onion", "kind": "dish"}, {"name": "Sykoti", "note": "fried liver, lemon, quick heat", "kind": "dish"}, {"name": "Keftedakia", "note": "small crisp meatballs, herb and cumin", "kind": "dish"}, {"name": "Pancetta", "note": "griddled cured pork, salty and charred", "kind": "dish"}, {"name": "Chyma krasi", "note": "barrel wine by the karafa, rough and cold", "kind": "drink"}], "price_range": "€–€€", "reservation": "Advisable at weekends", "best_time": "A warm summer night in the courtyard", "status": "unverified", "statusChecked": "2026-10-14", "hook": "A 1958 koutouki in Palaia Kokkinia, its covered courtyard built around an old whitewashed fig tree.", "web": "https://tokoutoukitantoni.gr", "category": "koutoukia", "hot_this_month": "Bakaliaros-skordalia weather under the covered fig-tree yard; closed Mondays, open Tue-Sat 12:00-24:00 and Sunday to 17:00 per the venue record (checked 14 Oct 2026).", "charter": {"price": "€–€€", "book": "Advisable at weekends", "warn": "Not for the design-conscious or the hurried — deliberately old, tiled and floral; the joy is the courtyard, not the plating.", "fit": "A 1958 koutouki in Palaia Kokkinia, its covered courtyard built around an old whitewashed fig tree."}},
    {"id": "alargino", "cat": "shop", "tier": "plenty", "priority": 18, "badge": "Smyrna", "name": "Alargino", "short": "Alargino", "lat": 37.9663, "lng": 23.65285, "neighborhood": "Nikaia · Agiou Ioannou, near the centre", "tags": ["€€ · ~€15–20pp", "Advisable on music nights", "A music night, for old-Kokkinia atmosphere"], "productTags": ["Smyrna soutzoukakia", "Pastourmalopita", "Live music"], "why": "The name comes from an old island word for far away, and the Smyrna Association of Nikaia and Piraeus used the same word to title one of its own music-and-dance shows. The kitchen leans on the dishes the 1922 refugees carried west, starting with hand-rolled cumin soutzoukakia and pastourma pie, then goes off to the Tzoumerka for pork tigania and to Crete for snail stifado. On Saturdays a rebetiko trio plays the Smyrna repertoire.", "address": "Agiou Ioannou 2, Nikaia 184 50", "phone": "+30 210 4910770", "hours": "Call ahead: one listing (Mood) gives Fri and Sat 15:00-02:00; other days not found", "maps": "https://www.google.com/maps/search/?api=1&query=Alargino+Nikaia", "verdict": "The neighbourhood table that keeps Smyrna on the plate — handmade Smyrnaïka soutzoukakia and pastourma pie under live strings.", "signature": "Smyrnaïka soutzoukakia: handmade cumin-scented mince in tomato, the refugee city on a plate.", "caveat": "Not a quiet or gourmet room — a loud, music-filled neighbourhood mezedopoleio, not a destination showpiece.", "signal_chip": {"label": "In2life", "full": "In2life 2023 — 'the best mezedes of Nikaia'", "cosign": "the table that keeps Smyrna on the plate."}, "dishes": [{"name": "Soutzoukakia Smyrnaïka", "note": "handmade cumin-scented mince in tomato sauce", "kind": "dish"}, {"name": "Pastourmalopita", "note": "pastourma-and-cheese pie, spiced and molten", "kind": "dish"}, {"name": "Melitzanes gemistes", "note": "stuffed eggplant, Anatolian-leaning", "kind": "dish"}, {"name": "Hoirini tiganià", "note": "pan-fried pork in the Tzoumerka style", "kind": "dish"}, {"name": "Saligkaria stifado", "note": "snails braised Cretan-style with onions", "kind": "dish"}], "price_range": "€€ · ~€15–20pp", "reservation": "Advisable on music nights; phone +30 210 4910770", "best_time": "A music night, for old-Kokkinia atmosphere", "status": "confirmed", "hook": "A Nikaia meze house in a 1938 building, with Smyrna soutzoukakia and rebetiko trios at weekends", "statusChecked": "2026-10-14", "category": "refugee", "hot_this_month": "Autumn weekends bring the live strings back indoors; book a weekend music night for the Smyrna soutzoukakia (checked 14 Oct 2026).", "charter": {"price": "€€ · ~€15–20pp", "book": "Advisable on music nights; phone +30 210 4910770", "warn": "Not a quiet or gourmet room — a loud, music-filled neighbourhood mezedopoleio, not a destination showpiece.", "fit": "A Nikaia meze house in a 1938 building, with Smyrna soutzoukakia and rebetiko trios at weekends"}},
    {"id": "taverna-tou-katsogiannou", "cat": "shop", "tier": "plenty", "priority": 19, "badge": "Est.1930", "name": "Taverna tou Katsogiannou", "short": "Taverna tou Katsogiannou", "lat": 37.94594, "lng": 23.62744, "neighborhood": "Drapetsona · opposite the church of Agios Panteleimon", "tags": ["€€ · ~€15–25pp", "Advisable, especially weekends", "Lunch, for the magirefta and meatballs"], "productTags": ["Ouzo meatballs", "Magirefta", "Lamb chops"], "why": "It began around 1930 as a dairy shop opposite the church of Agios Panteleimon. Grigoris Katsogiannis started grilling salt cod and chops on charcoal, and by stages it became a grocery-taverna. Since 2005 Dora Stavridou has cooked here from family recipes: a handful of pot dishes that change daily, such as papoutsakia, moussaka and imam, plus fries she cuts by hand. A 1930 British Prestcold refrigerator with mirrored doors still stands in the room and still works.", "address": "Agiou Panteleimonos 15, Drapetsona 186 48", "phone": "+30 210 4613209", "hours": "Own site: Mon closed; Tue-Thu 13:00-22:30; Fri-Sat 13:00-23:00; Sun 13:00-17:00 (older listings differ slightly; call ahead on holidays)", "maps": "https://www.google.com/maps/search/?api=1&query=Taverna+tou+Katsogiannou+Drapetsona", "verdict": "The oldest taverna in Drapetsona (since 1930), where Dora Stavridou's ouzo-doused meatballs in red sauce have become, in the local phrase, 'an urban myth.'", "signature": "Keftedakia me ouzo: ouzo-flambéed meatballs in red sauce, hand-cut fries for dipping.", "caveat": "Not for a big fish spread: meat and magirefta only. Closed Mondays, Sunday lunch only.", "person": "Opened 1930 as a dairy shop by Grigoris Katsogiannis; since 2005 run by Dora (Theodora) Stavridou, who cooks about six daily-changing dishes from family recipes and hand-cuts the fries.", "signal_chip": {"label": "13.5/20", "full": "Athinorama 2023 — critics' review, 13.5/20", "cosign": "the oldest taverna in Drapetsona."}, "dishes": [{"name": "Keftedakia me ouzo", "note": "ouzo-flambéed meatballs in red sauce; hand-cut fries to dip", "kind": "dish"}, {"name": "Paidakia (lamb chops)", "note": "finely cut, exceptionally juicy and delicate off the coals", "kind": "dish"}, {"name": "Smyrneiko kaiserli", "note": "Smyrna-style baked meat, warm spice, tender", "kind": "dish"}, {"name": "Bakaliaros tiganitos", "note": "old-Piraeus fried salt cod, crisp-battered", "kind": "dish"}, {"name": "Magirefta tis imeras", "note": "about six home-cooked dishes rotating daily", "kind": "dish"}, {"name": "Patates tiganites", "note": "cut by hand by Dora, fried fresh", "kind": "dish"}], "price_range": "€€ · ~€15–25pp", "reservation": "Advisable, especially weekends", "best_time": "Lunch, for the magirefta and meatballs", "status": "unverified", "hook": "Drapetsona's oldest taverna, a 1930s dairy turned grill, known for Dora's ouzo-doused meatballs", "web": "https://www.tavernatoukatsogiannou.gr/", "statusChecked": "2026-10-14", "category": "refugee", "charter": {"price": "€€ · ~€15–25pp", "book": "Advisable, especially weekends", "warn": "Not for a big fish spread: meat and magirefta only. Closed Mondays, Sunday lunch only.", "fit": "Drapetsona's oldest taverna, a 1930s dairy turned grill, known for Dora's ouzo-doused meatballs"}},
    {"id": "vosporos", "cat": "shop", "tier": "plenty", "priority": 29, "badge": "Politiki", "name": "Vosporos", "short": "Vosporos", "lat": 37.93881, "lng": 23.65985, "neighborhood": "Mikrolimano · Akti Koumoundourou quay", "tags": ["€€ · ~€25–30pp", "Recommended; book a music night", "Dinner, a night with live politika/smyrneika"], "productTags": ["Politiki kouzina", "Peinirli", "Live music"], "why": "The Mikrolimano quay is lined with fish tavernas, and Vosporos is the one that cooks the Bosphorus instead, as it says it has for 22 years. On the table: the dishes of the Constantinople Greeks, such as adana kebab with yogurt, hunkar begendi over smoked aubergine, pastourma and soutzouki, and a peinirli big enough to share, finished with bougatsa. Chef Sophia Koletsiou told Country & Town House this is where she eats off duty when she wants anything but fish.", "address": "Akti Koumoundourou 20, Mikrolimano, 185 33 Piraeus", "phone": "+30 210 412 7324", "hours": "Own site: daily 13:00-01:00 (older record had Sun from ~12:00; call ahead for Sunday lunch)", "maps": "https://www.google.com/maps/search/?api=1&query=Vosporos+Mikrolimano+Piraeus", "verdict": "Piraeus's one genuine Politiki-cuisine table — Bosphorus meat-and-mezze in outsized portions, where a Piraeus chef sends you when she wants everything but fish.", "signature": "Oversized peinirli: a boat of molten four-cheese and pastourma, straight from the oven.", "caveat": "Not for small appetites or fish-taverna seekers — meat- and mezze-heavy Politiki cooking in enormous portions, not Aegean seafood.", "signal_chip": {"label": "Chef pick", "full": "Country & Town House — chef Sophia Koletsiou eats here", "cosign": "her Politiki table off-duty (single-source, kept honest)."}, "dishes": [{"name": "Oversized peinirli", "note": "the famously huge cheese-filled boat, its calling card", "kind": "dish"}, {"name": "Politiko saganaki", "note": "halloumi fried hot, squeaky and golden", "kind": "dish"}, {"name": "Adana / sis kebab", "note": "spiced grilled meat, fluffy and juicy with yogurt", "kind": "dish"}, {"name": "Hunkar begendi", "note": "braised lamb over smoky eggplant purée", "kind": "dish"}, {"name": "Pastourma & soutzouki", "note": "cured Constantinople meats, garlicky and spiced", "kind": "dish"}, {"name": "Bougatsa", "note": "chef Koletsiou's dessert pick — creamy phyllo", "kind": "sweet"}], "price_range": "~25-30 euros pp (e-restaurants listing)", "reservation": "Recommended; listings say tables are hard to get at peak times", "best_time": "Dinner, a night with live politika/smyrneika", "status": "unverified", "hook": "Constantinople-style meat and mezze on the Mikrolimano quay, with live politika songs some nights", "web": "https://www.vosporos.com/", "statusChecked": "2026-10-14", "category": "other", "charter": {"price": "~25-30 euros pp (e-restaurants listing)", "book": "Recommended; listings say tables are hard to get at peak times", "warn": "Not for small appetites or fish-taverna seekers — meat- and mezze-heavy Politiki cooking in enormous portions, not Aegean seafood.", "fit": "Constantinople-style meat and mezze on the Mikrolimano quay, with live politika songs some nights"}},
    {"id": "toukta-thai-food", "cat": "shop", "tier": "plenty", "priority": 20, "badge": "6 tables", "name": "Toukta Thai Food", "short": "Toukta Thai Food", "lat": 37.9669, "lng": 23.64506, "neighborhood": "Nikaia · Ionias & Thrakis, the 1922 refugee grid", "tags": ["€ · mains ~€7", "Advisable — only ~6 tables", "Book ahead; the tiny room fills fast"], "productTags": ["Pad thai", "Thai curry", "€7 plates"], "why": "On the corner of Ionias and Thrakis, streets named for the lost homelands of the 1922 refugees, a Thai family has taken over an old neighbourhood kafeneio and turned it into a small Thai taverna. Uthaiwan Wannasuk pounds her own curry pastes. One review says she runs it with her daughter, walk-in style, with plates between roughly 4 and 10 euros, and some dishes now go out for delivery.", "address": "Ionias 3 & Thrakis, Nikaia 184 50", "phone": "+30 210 4908866", "hours": "Call ahead: Wolt shows delivery only Wed-Fri 16:00-19:00; dine-in hours not found", "maps": "https://www.google.com/maps/search/?api=1&query=Toukta+Thai+Food+Nikaia", "verdict": "Proof Kokkinia's immigrant table didn't end in 1922 — a six-table Thai kitchen turning out the real, fresh-pounded thing at €7 a plate.", "signature": "Pad thai: tamarind-slicked rice noodles, peanuts, lime, wok-hot and fresh.", "caveat": "Not for the taverna-traditionalist or big groups — a cramped six-table room with no Greek-classics menu.", "person": "Owner-cook Uthaiwan Wannasuk, who pounds her own curry pastes and folds fresh pad thai for six tables at a time.", "signal_chip": {"label": "FlagLife", "full": "FlagInLife 2024 — 'an unexpected Thai experience in Nikaia'", "cosign": "the immigrant table Kokkinia kept after 1922."}, "dishes": [{"name": "Pad thai", "note": "tamarind rice noodles, peanuts, lime, wok-fresh", "kind": "dish"}, {"name": "Spicy soup (minced meat)", "note": "hot-sour broth with fresh chilli and herbs", "kind": "dish"}, {"name": "Thai curry", "note": "coconut curry, fragrant, made to order", "kind": "dish"}, {"name": "Steamed jasmine rice", "note": "the fluffy base for every plate", "kind": "dish"}, {"name": "Thai iced tea", "note": "sweet, orange-hued brew over ice", "kind": "drink"}], "price_range": "~4-10 euros a plate (one review)", "reservation": "Advisable — only ~6 tables", "best_time": "Book ahead; the tiny room fills fast", "status": "unverified", "hook": "A tiny Thai kitchen in an old Nikaia kafeneio, curry pastes pounded in-house, plates under 10 euros", "web": "https://www.facebook.com/touktathaifood/", "statusChecked": "2026-10-14", "category": "other"},
    {"id": "sushi-rolls", "cat": "shop", "tier": "plenty", "priority": 21, "badge": "Sushi", "name": "Sushi Rolls", "short": "Sushi Rolls", "lat": 37.93838, "lng": 23.64045, "neighborhood": "Piraeus centre · behind Agios Nikolaos, near Akti Miaouli", "tags": ["€€ · intimate sushi bar", "Advisable — small room", "Weekday evening, when the offices empty"], "productTags": ["Sushi", "Sake", "Shipping canteen"], "why": "The church behind it is dedicated to Saint Nicholas, patron of sailors, and the streets around it hold the offices of Greek shipping. For about ten years this small room has been where those offices eat, and Athens Voice described it as a meeting point for people from the nearby shipping companies. The fish is bought from Greek suppliers. Reviewers single out the crispy duck, mango and dragon rolls and a kani-ebi tartare, served on sugar-cane plates.", "address": "Agiou Nikolaou 3, Piraeus", "phone": "+30 210 4284439", "hours": "Call ahead: Wolt shows Mon-Thu 12:30-23:15, Fri 12:30-23:45, Sat 14:00-23:45, Sun closed (delivery hours); old record says evenings", "maps": "https://www.google.com/maps/search/?api=1&query=Sushi+Rolls+Piraeus", "verdict": "The reliable non-Greek table with a story — a shipping-office-canteen sushi bar behind the seamen's church, cut to order for the people who move ships.", "signature": "Crispy Salmon & Tuna Garlic rolls: cut to order, with cold or warm sake.", "caveat": "Not a headline — Piraeus's real 'foreign' greatness is the refugee kitchen; this is the reliable, honest table with a story.", "signal_chip": {"label": "AthensVce", "full": "Athens Voice 2025 — 'a diamond of Japanese cuisine in Piraeus'", "cosign": "solid, not a headline — the canteen for the people who move ships."}, "dishes": [{"name": "Crispy Salmon roll", "note": "a house signature, crunch and richness", "kind": "dish"}, {"name": "Tuna Garlic roll", "note": "the other signature, punchy and clean", "kind": "dish"}, {"name": "Nigiri selection", "note": "cut-to-order over Greek-sourced fish", "kind": "dish"}, {"name": "Sake (cold / warm)", "note": "the correct pour", "kind": "drink"}, {"name": "Asahi", "note": "the reliable Japanese lager", "kind": "drink"}], "price_range": "€€ · intimate sushi bar", "reservation": "Advisable — small room", "best_time": "Weekday evening, when the offices empty", "status": "unverified", "hook": "A small sushi bar behind Agios Nikolaos that works as the lunch canteen for Piraeus shipping offices", "web": "https://sushirolls.gr/", "statusChecked": "2026-10-14", "category": "other"},
    {"id": "o-giorgos", "cat": "berth", "tier": "berth_top", "priority": 3, "badge": "€2.50", "name": "O Giorgos", "short": "O Giorgos", "lat": 37.94619, "lng": 23.64438, "neighborhood": "Central Piraeus · Gounari, by the old flea market", "tags": ["€ · wrap ~€2.50", "No — corner counter", "Weekday lunch, straight off the grill"], "productTags": ["Meatball wrap", "€2.50", "Red sauce"], "why": "Grigoris Tsakiris and his son Giorgos opened in 2019 among the junk dealers behind the fish market, wanting souvlaki the way it used to be made. The menu is short: a wrap of two small beef patties, mixed daily and grilled when you order, or a plate of six, with tomato, onion, parsley, red sauce and a hot pepper. The pita is their own recipe, made by hand without preservatives. There are no fries, no tzatziki and no other sauces.", "address": "Dimitriou Gounari 18 & Nikita, Piraeus", "phone": "+30 211 4033388", "hours": "Call ahead: old record has weekdays ~11:00-20:30, Sat to ~19:30; an older press source gives weekdays 11:00-19:00, Sat to 18:00; queues reported from 11:00", "maps": "https://www.google.com/maps/search/?api=1&query=O+Giorgos+souvlaki+Piraeus", "verdict": "Piraeus's cult modern souvlaki — a ~€2.50 hand-formed beef-meatball wrap that locals and the food press repeatedly rank the city's best.", "signature": "Bifteki wrap: two hand-formed beef meatballs, salt and pepper, soft pita, spicy red sauce.", "caveat": "Not for a sit-down dinner — daytime only, closes early evening, seating barely there.", "person": "Grigoris Tsakiris and his son Giorgos, who opened the shop in 2019 in the old flea-market lanes wanting to make souvlaki 'as it used to be'.", "signal_chip": {"label": "#1 top-5", "full": "in2life 2025 — #1 of Piraeus's top-five souvlaki", "cosign": "a €2.50 wrap a small cult formed around."}, "dishes": [{"name": "Bifteki (meatball) souvlaki", "note": "two hand-formed beef keftedakia, salt-pepper only, in soft pita", "kind": "dish"}, {"name": "Pork kalamaki", "note": "skewered pork of praised quality, charcoal-juicy and lean", "kind": "dish"}, {"name": "Homemade red sauce", "note": "house spicy red sauce that lifts every wrap", "kind": "dish"}, {"name": "Pita", "note": "soft handmade pita, the wrap's warm envelope", "kind": "dish"}, {"name": "Tomato & onion", "note": "fresh raw dressing, no fries stuffed inside", "kind": "dish"}], "price_range": "€ · wrap ~€2.50", "reservation": "No — corner counter", "best_time": "Weekday lunch, straight off the grill", "status": "confirmed", "hook": "A daytime corner grill in the old flea-market lanes with a cult following for its beef-meatball wrap", "web": "https://www.facebook.com/Yorgossouvlaki/", "statusChecked": "2026-10-14", "category": "souvlaki"},
    {"id": "souvlakia-o-serkos", "cat": "shop", "tier": "plenty", "priority": 17, "badge": "Armenian", "name": "Souvlakia o Serkos", "short": "Souvlakia o Serkos", "lat": 37.96339, "lng": 23.65458, "neighborhood": "Kokkinia · Plateia Neraidas, behind Thivon", "tags": ["€ · cheap grill fare", "No", "Early evening, when the plateia fills"], "productTags": ["Armenian kebab", "Soutzouki", "Pastourma"], "why": "Sarkis 'Serkos' Hanikyan reached Kokkinia among the Armenians who survived Smyrna. He sold nuts from a cart near the old Esperos cinema before learning to grind and grill kebab, and in 1972 he opened his first shop. The recipe has not changed since: beef and lamb mince, salt, pepper and charcoal, no strong spice. His children run the grill now, and the tables spill onto the square in the old refugee grid behind Thivon.", "address": "Ionos Dragoumi 39-41, Kokkinia, Piraeus 185 42", "phone": "+30 210 4928297", "hours": "Midday into evening; call to confirm", "maps": "https://www.google.com/maps/search/?api=1&query=Souvlakia+o+Serkos+Kokkinia", "verdict": "Piraeus's last Armenian charcoal kebab — a refugee family's salt-and-pepper mince that shames every over-spiced imitation.", "signature": "Armenian kebab: lamb-and-beef mince, only salt and pepper, charcoal-blistered, pillow-soft.", "caveat": "Not for spice-seekers or a polished dinner — a plateia grill shack, a handful of items, cash.", "person": "Opened by Sarkis 'Serkos' Hanikyan, an Armenian who began as a street nut-vendor before mastering the kebab (LiFO gives 1972); today his daughter Agavni ('Anni') works the charcoal and his son Evendis runs the shop.", "signal_chip": {"label": "LiFO", "full": "LiFO 2021 — 'the authentic Armenian kebab of Serkos'", "cosign": "the port's last Armenian charcoal grill."}, "dishes": [{"name": "Armenian kebab", "note": "lamb-and-beef mince, salt and pepper only, charcoal-charred", "kind": "dish"}, {"name": "Soutzouki (handmade)", "note": "house-made spiced sausage, blistered on charcoal", "kind": "dish"}, {"name": "Pastourma salad", "note": "Greek salad crowned with cured, fenugreek-spiced beef pastourma", "kind": "dish"}, {"name": "Pork souvlaki", "note": "simple skewer off the same fire", "kind": "dish"}, {"name": "Pita", "note": "char-grilled flatbread to wrap the mince", "kind": "dish"}], "price_range": "Kebab ~2 euros a piece; plate with two pitas, tomato, onion and tzatziki from ~9 euros (efood listing)", "reservation": "No", "best_time": "Early evening, when the plateia fills", "status": "confirmed", "hook": "An Armenian refugee family's charcoal kebab on Plateia Neraidas, salt and pepper only, since 1972", "statusChecked": "2026-10-14", "category": "souvlaki"},
    {"id": "o-karabelas", "cat": "shop", "tier": "plenty", "priority": 23, "badge": "Gyro €3", "name": "O Karabelas", "short": "O Karabelas", "lat": 37.94401, "lng": 23.65624, "neighborhood": "Neo Faliro edge · Pylis, near Karaiskakis Stadium", "tags": ["€ · wrap ~€3", "No — standing room", "Early evening, before the gyro sells out"], "productTags": ["Gyros", "Red sauce", "Olympiacos"], "why": "The shop is a few minutes' walk from Olympiacos's Karaiskakis ground, and its walls are covered with the club's scarves, photographs and pennants. Spiros and Eleni have run it for about thirty of its nearly fifty years. They turn the gyro by hand and grill the patties and skewers in front of you, and they make the slightly hot red sauce that regulars come back for. The gyro can sell out early in the evening.", "address": "Pylis 51-53, Piraeus (sources give both 51 and 53)", "phone": "+30 210 4112622", "hours": "Evenings from ~18:00; closed Sunday", "maps": "https://www.google.com/maps/search/?api=1&query=O+Karabelas+Piraeus", "verdict": "The most atmospheric old-school souvlatzidiko in Piraeus — half Olympiacos museum, half standing-room grill, still turning out ~€3 wraps after nearly fifty years.", "signature": "Gyros pita: pork gyro, warm pita, the slightly spicy house red sauce.", "caveat": "Not for a comfortable meal or the sauce-shy — a cramped, standing-room grill, evenings only.", "person": "Run for roughly three decades by Spiros and Eleni (Eleni Barkolia is the registered proprietor); walls packed floor-to-ceiling with Olympiacos memorabilia, a short walk from the club's Karaiskakis ground.", "signal_chip": {"label": "in2life", "full": "in2life 2025 — a Piraeus top-five souvlaki", "cosign": "half Olympiacos museum, half standing-room grill."}, "dishes": [{"name": "Gyros pita", "note": "hand-turned gyro, warm pita, the slightly spicy red sauce", "kind": "dish"}, {"name": "Chicken kalamaki", "note": "skewered chicken off the charcoal, made in-house", "kind": "dish"}, {"name": "Keftedaki (meatball)", "note": "seasoned hand-formed meatball tucked into the wrap", "kind": "dish"}, {"name": "House red sauce", "note": "slightly spicy red sauce that is the shop's signature", "kind": "dish"}, {"name": "Burger", "note": "house burger for the non-souvlaki eater", "kind": "dish"}], "price_range": "€ · wrap ~€3", "reservation": "No — standing room", "best_time": "Early evening, before the gyro sells out", "status": "confirmed", "hook": "A near-fifty-year-old gyro counter by Karaiskakis, its walls packed with Olympiacos memorabilia", "statusChecked": "2026-10-14", "category": "souvlaki"},
    {"id": "mastronikolas", "cat": "shop", "tier": "plenty", "priority": 25, "badge": "Est.1909", "name": "Mastronikolas", "short": "Mastronikolas", "lat": 37.9427, "lng": 23.65195, "neighborhood": "Kastella · Karaoli & Dimitriou avenue", "tags": ["€ · a few euros a slice", "Walk-in; counter service", "Mid-morning, a warm slice with Greek coffee"], "productTags": ["Galaktoboureko", "Rizogalo", "Kaimaki ice"], "why": "The business started in 1909 as a dairy shop that also ran a taverna. The grandfather delivered milk by donkey around Profitis Ilias, and the family still keeps his tin milk can. Over time the taverna gave way to pastry, and galaktoboureko became the main trade: sheep's-butter custard under crisp phyllo, sold by the piece from big trays or in round pans, with a kataifi version too. Cookout/SKAI reported orders coming from as far as Sweden.", "address": "Karaoli & Dimitriou 68, Piraeus 185 34", "phone": "+30 210 4123783", "hours": "Mon–Sat 08:30–22:00, Sun 09:00–22:00", "maps": "https://www.google.com/maps/search/?api=1&query=Mastronikolas+galaktopoleio+Piraeus", "verdict": "The oldest galaktopoleio in Piraeus (since 1909), whose generous, crisp-topped galaktoboureko ranks among the best in Attica.", "signature": "Galaktoboureko: warm, semolina custard oozing under shatter-crisp golden phyllo.", "caveat": "A sweets counter to take away from, with no savoury breakfast. A second branch operates in Pigada.", "person": "Panagiotis Mastronikolas, third-generation owner (his newborn son the fourth); his grandfather delivered milk around Profitis Ilias by donkey from 1909, and the family keeps the original tin milk-can.", "signal_chip": {"label": "SKAI", "full": "Cookout/SKAI 2024 — 'the historic galaktopoleio of Piraeus'", "cosign": "the port's oldest, since 1909."}, "dishes": [{"name": "Galaktoboureko", "note": "semolina custard, crackling phyllo, light syrup; round pans or big trays", "kind": "sweet"}, {"name": "Rizogalo", "note": "thick milky rice pudding with a baked skin on top", "kind": "sweet"}, {"name": "Krema", "note": "old-recipe vanilla cream, silky and pure", "kind": "sweet"}, {"name": "Kaimaki ice cream", "note": "sheep-and-cow's-milk ice cream, mastic-chewy, made in-house", "kind": "sweet"}, {"name": "Strained sheep's-milk yogurt", "note": "under a thick skin, from the same counter", "kind": "buy"}], "price_range": "€ · a few euros a slice", "reservation": "Walk-in; counter service", "best_time": "Mid-morning, a warm slice with Greek coffee", "status": "unverified", "hook": "Piraeus's oldest galaktopoleio, in the family since 1909, cutting galaktoboureko by the slab", "statusChecked": "2026-10-14", "category": "breakfast"},
    {"id": "euxeinon", "cat": "shop", "tier": "plenty", "priority": 26, "badge": "Piroski", "name": "Euxeinon", "short": "Euxeinon", "lat": 37.94101, "lng": 23.64356, "neighborhood": "Trouba · Navarchou Notara, by the port", "tags": ["€ · a couple of euros each", "No — grab-and-go", "Mid-morning, when the fryer is going"], "productTags": ["Piroski", "Pontic recipe", "Dawn fry"], "why": "Parthenopi Amanatidou carried her piroski recipe from Trebizond to Constantinople, then to Greece in the 1922 expulsion. Her family says nostalgia for the lost city pushed her to open the first Pontic piroski workshop in Piraeus in 1976. In the 1990s her son Spyros, a sea captain often away for months, and his wife Vasiliki trained beside her to carry it on. The shop has since moved to Notara 50 and taken the name Euxeinon, the ancient name for the Black Sea.", "address": "Navarchou Notara 50, Piraeus 185 35", "phone": "+30 213 0280000", "hours": "Mornings from ~03:00 bake until the midday sellout", "maps": "https://www.google.com/maps/search/?api=1&query=Euxeinon+piroski+Piraeus", "verdict": "The best-loved piroski in Piraeus — a half-century Pontic-refugee bakery frying cheese and mince pockets golden to order from an unbroken family recipe.", "signature": "Piroski kima: golden, blistered mince pocket, fried to order and eaten scalding.", "caveat": "Fried, hearty and gone by midday — not for a light, sweet or late breakfast; a grab-and-go counter.", "person": "Founded 1977 by Parthenope (Partheni) Amanitidou, a 1922 refugee from Trebizond; now run by her son Spyros and his wife Vasiliki, with grandsons Giorgos and Haris on the counter.", "signal_chip": {"label": "LiFO", "full": "LiFO 2022 — among the best piroski in Piraeus", "cosign": "a Pontic recipe carried from Trebizond in 1922."}, "dishes": [{"name": "Piroski kima (mince)", "note": "fried mince pocket, golden fluffy dough, juicy filling", "kind": "dish"}, {"name": "Piroski tyri (cheese)", "note": "molten cheese inside a crisp fried shell, with Mytilene kaseri", "kind": "dish"}, {"name": "Piroski patata", "note": "Naxos-potato piroski, soft and comforting", "kind": "dish"}, {"name": "Peinirli me pastourma (Sat)", "note": "Saturday-only boat-dough peinirli with spiced pastourma", "kind": "dish"}, {"name": "Saturday pastitsio", "note": "baked layered pasta by the family's economist son", "kind": "dish"}, {"name": "Greek coffee", "note": "a quick coffee to see off the pie", "kind": "drink"}], "price_range": "€ · a couple of euros each", "reservation": "No — grab-and-go", "best_time": "Mid-morning, when the fryer is going", "status": "unverified", "hook": "A Pontic piroski workshop by the ferry gates, frying a Trebizond family recipe from before dawn", "web": "http://www.piroski-euxeinon.gr/", "statusChecked": "2026-10-14", "category": "breakfast"},
    {"id": "bougatsa-pavlidi", "cat": "shop", "tier": "plenty", "priority": 27, "badge": "24 hours", "name": "Bougatsa Pavlidi", "short": "Bougatsa Pavlidi", "lat": 37.9731, "lng": 23.66024, "neighborhood": "Nikaia · Petrou Ralli, near the state hospital", "tags": ["€ · a couple of euros each", "None — walk-up counter, no seats", "3–6 a.m., phyllo hot off the tray"], "productTags": ["Bougatsa", "24-hour", "Phyllo pies"], "why": "Leonidas Pavlidis learned to stretch phyllo from a Pomak baker in Sapes, in Rhodope, and opened here in 1974, when Petrou Ralli was still unpaved. Through the 1970s to the 1990s, night-owl musicians came at three in the morning for sweet bougatsa instead of tripe soup. His daughter Sophia Dridaki-Pavlidi runs it now, with her son Giorgos learning the trade. To Vima wrote about it in March 2026, and it still bakes before dawn.", "address": "Petrou Ralli 168, Nikaia 184 54", "phone": "+30 210 4955540", "hours": "Call ahead: LiFO and To Vima (Mar 2026) say open 24 hours; a Psaxno listing shows Wednesday closed", "maps": "https://www.google.com/maps/search/?api=1&query=Bougatsa+Pavlidi+Nikaia", "verdict": "The last 24-hour phyllo workshop in working-class Piraeus, still turning out the port's benchmark bougatsa fresh before dawn.", "signature": "Sweet bougatsa: crackling hot phyllo, warm semolina cream, caramelised sugar, cinnamon dust.", "caveat": "Not a café — no seats, no coffee ritual, no view; a bakery counter deep in residential Nikaia, a bus or taxi from the harbour.", "person": "Sophia Dridaki-Pavlidi runs it, continuing her father Leonidas Pavlidis, who learned to stretch phyllo from a Pomak baker in Sapes (Rhodope) and opened here in 1974; her son Giorgos is learning the trade.", "signal_chip": {"label": "LiFO", "full": "LiFO 2021 — named the best bougatsa in Piraeus", "cosign": "the port's last 24-hour phyllo workshop."}, "dishes": [{"name": "Sweet bougatsa (γλυκιά)", "note": "hand-stretched phyllo, warm semolina cream, crystal-sugar caramel crust, cinnamon", "kind": "sweet"}, {"name": "Savoury bougatsa with feta", "note": "salty feta folded in blistered phyllo, never greasy", "kind": "dish"}, {"name": "Piroski", "note": "fried rolls: potato-sausage, turkey-cheese, or bacon and cream cheese", "kind": "dish"}, {"name": "Peinirli", "note": "dough boat of minced meat and cheese, or ham and bacon", "kind": "dish"}, {"name": "Kimadopita", "note": "peppery, generous minced-meat pie", "kind": "dish"}, {"name": "Tyropita", "note": "cheese pie in the same hand-pulled phyllo, any hour", "kind": "dish"}], "price_range": "€ · a couple of euros each", "reservation": "None — walk-up counter, no seats", "best_time": "3–6 a.m., phyllo hot off the tray", "status": "confirmed", "hook": "A round-the-clock phyllo workshop in Nikaia since 1974, still the port's reference bougatsa", "statusChecked": "2026-10-14", "category": "late-night"},
    {"id": "kantina-o-plastiras", "cat": "shop", "tier": "plenty", "priority": 28, "badge": "Port quay", "name": "Kantina o Plastiras", "short": "Kantina o Plastiras", "lat": 37.94462, "lng": 23.63081, "neighborhood": "Drapetsona · Akti Vasileiadi, Lipasmata quay (Gate E1/E2)", "tags": ["€ · a couple of euros a kalamaki", "None — plastic tables on the quay", "Late, after the bouzoukia or a night ferry"], "productTags": ["Kalamaki", "Port canteen", "Late-night"], "why": "The canteen stands among the trucks at Gate E2, opposite the Crete ferries, beside the derelict conveyor that once loaded fertiliser from the Lipasmata works onto ships. The owner, Fortetsanakis, is known as Plastiras and says he is a baptismal godson of General Nikolaos Plastiras, so the general's portraits cover the walls. Chef Vasilis Kallidis has named its pork kalamaki as his favourite street food and put it among the five best souvlaki in Athens.", "address": "Akti Vasileiadi (Gate E1/E2), Drapetsona 186 48", "phone": "+30 210 4633820", "hours": "Call ahead: ask4food says from early morning, Mon-Fri; old record says it also runs late after nights out. Not reconciled", "maps": "https://www.google.com/maps/search/?api=1&query=Kantina+o+Plastiras+Drapetsona", "verdict": "Some of the best souvlaki in the city is grilled on a dystopian Drapetsona quay by a man who claims General Plastiras himself as his godfather.", "signature": "Pork kalamaki: charred and juicy, with grilled bread to mop the pan juices.", "caveat": "Not for comfort, a real menu or the pretty side of Piraeus — a truckers' canteen in a raw industrial no-man's-land, hours unpredictable.", "person": "The owner, nicknamed 'Plastiras' (surname Fortetsanakis), says he is a baptismal godson of General/PM Nikolaos Plastiras — hence the wall of the general's portraits; he runs it with his wife Anna.", "signal_chip": {"label": "Kallidis", "full": "LiFO — chef Vasilis Kallidis's port-canteen pick", "cosign": "a chef-grade signal on a truckers' quay."}, "dishes": [{"name": "Pork kalamaki", "note": "skewers grilled to order, juicy inside, smoky edges, bread to soak the juices", "kind": "dish"}, {"name": "Chicken kalamaki", "note": "the lighter skewer, same charcoal char", "kind": "dish"}, {"name": "Fresh-cut fries", "note": "fried on the spot, salty, made for soaking up the night", "kind": "dish"}, {"name": "Feta with oregano", "note": "a slab of feta, olive oil, oregano", "kind": "dish"}, {"name": "Cold beer", "note": "icy beer at a plastic table on the quay", "kind": "drink"}], "price_range": "Up to ~15 euros pp (e-table)", "reservation": "None — plastic tables on the quay", "best_time": "Late, after the bouzoukia or a night ferry", "status": "unverified", "hook": "A truckers' canteen at port Gate E2, grilling the pork skewers chef Vasilis Kallidis calls the city's best", "statusChecked": "2026-10-14", "category": "late-night"}
