  const PHOTOS = [{"src": "/terroir/Piraeus-Saronic/img/piraeus-1-mikrolimano-munichia-har.jpg", "caption": "The little harbour of Mikrolimano beneath the amphitheatre of Kastella, Piraeus (2022). Photo: Pavlos1988, Wikimedia Commons, CC BY-SA 4.0.", "credit": "Pavlos1988 / Wikimedia Commons · CC BY-SA 4.0"}, {"src": "/terroir/Piraeus-Saronic/img/piraeus-2-zea-marina-pasalimani-th.jpg", "caption": "Zea Marina (Pasalimani), the circular ancient war-harbour of Piraeus, today a yacht and fishing marina (2015). Photo: Palickap, Wikimedia Commons, CC BY-SA 4.0.", "credit": "Palickap / Wikimedia Commons · CC BY-SA 4.0"}, {"src": "/terroir/Piraeus-Saronic/img/piraeus-3-the-piraeus-apollo-bronz.jpg", "caption": "The Piraeus Apollo, a bronze kouros unearthed in 1959 during drainage/sewer excavation in the town of Piraeus (near the Agia Triada church), Archaeological Museum of Piraeus. Photo: Deiadameian, Wikimedia Commons, CC BY-SA 4.0.", "credit": "Deiadameian / Wikimedia Commons · CC BY-SA 4.0"}];
  const GEMS = [{"id": "gem-garides-saganaki", "pattern": "garides saganaki", "tag": "Piraeus gem · born here", "name": "The shrimp born in Tourkolimano", "story": "Every Greek taverna lists it now, and most diners take it for old village cooking. It is not: the plate was worked out in the 1960s in the fish houses of this crescent, when Mikrolimano still wore its Ottoman name, Tourkolimano. No single kitchen can prove it invented the dish; the credit belongs to the harbour. The Dish, at the foot, has the technique.", "where": "Dourabeis on Akti Dilaveri keeps it on the list."}, {"id": "gem-kakavia", "pattern": "kakavia", "tag": "Piraeus gem · dish", "name": "The fisherman's soup that became a Michelin plate", "story": "The tripod pot, the kakavi, gave the soup its name; the rockfish nobody would buy gave it its body. Lore calls it the ancestor of bouillabaisse: folk history, best held lightly. The Dish, at the foot, has how it is made.", "where": "Varoulko Seaside on the Mikrolimano marina."}, {"id": "gem-ichthyoskala", "pattern": "the ichthyoskala", "tag": "Piraeus gem · provisioning", "name": "The dawn auction, not a food hall", "story": "A wholesale auction, not a sight: it runs in the dark on the Keratsini edge, and by mid-morning the floor is hosed down and empty. It is often called the largest fish market in Greece, a claim easier to make than to measure. The larder card has the hours.", "where": "Eat its catch at Oinomageireio o Vasilis, among the auction's tables."}, {"id": "gem-gavros", "pattern": "gavros", "tag": "Piraeus gem · the wild fish", "name": "The small fish a farm can't fake", "story": "Greece farms more bream and bass than any other Mediterranean country, so 'fresh' and 'wild' read the same on a menu. The small blue fish cannot be farmed: gavros and marides are always caught, and seasonal by law — the purse-seine closes from 15 December to the end of February.", "where": "Margaro, by the Hellenic Naval Academy."}, {"id": "gem-taramosalata", "pattern": "taramosalata", "tag": "Piraeus gem · meze", "name": "The pale roe dip, not the pink one", "story": "Real tarama is pale: cured roe whipped with oil, lemon and soaked bread, no dye anywhere. Its roots run to the salted roe of the Byzantine coast and the Orthodox fasts, a soft 'roots in' rather than a dated record. Clean Monday is the day the whole city eats it.", "where": "Dourabeis makes its own."}, {"id": "gem-ouzo", "pattern": "ouzo", "tag": "Piraeus gem · the drink", "name": "The port's drink that isn't its own", "story": "The ouzeri is the port's daily rite, but the spirit is a guest here: its home is Lesvos, above all Plomari. And it is not a PDO but a protected Geographical Indication for spirits, reserved to Greece and Cyprus. The card under Ask for it by name has how to order it.", "where": "The ouzeri tables of Hatzikyriakio and Freattyda."}, {"id": "gem-astakomakaronada", "pattern": "astakomakaronada", "tag": "Piraeus gem · shellfish", "name": "The lobster pasta that started poor", "story": "On this quay it reads as the plate of money. Two corrections: the crustacean is usually the clawless Mediterranean langouste, not clawed lobster, and it is not old harbour grandeur — the crescent's grand fish houses date from about 1960.", "where": "Papaioannou, which also does a crayfish orzo."}];
